def decoded_texts(path):
    try:
        if os.path.getsize(path) > MAX_BYTES:
            return []
        with open(path, "rb") as stream:
            blob = stream.read()
    except OSError:
        return []
    texts = []
    for encoding in ("utf-8", "utf-16-le", "utf-16-be", "latin-1"):
        try:
            texts.append(blob.decode(encoding, errors="ignore"))
        except Exception:
            continue
    return texts


SKIP_DIRS = {
    "Cache", "Code Cache", "GPUCache", "GrShaderCache", "GraphiteDawnCache", "ShaderCache",
    "DawnCache", "DawnGraphiteCache", "DawnWebGPUCache", "Crash Reports", "Crashpad",
    "component_crx_cache", "extensions_crx_cache", "Safe Browsing", "Dictionaries",
    "FileTypePolicies", "optimization_guide_model_store", "screen_ai", "WidevineCdm",
}
PRIORITY_DIRS = {"Local Storage", "IndexedDB", "Session Storage"}


def walk_paths(root):
    """Yield the files below ``root``, application storage first and caches never."""
    if os.path.isfile(root):
        yield root
        return
    preferred = []
    rest = []
    for base, folders, names in os.walk(root):
        folders[:] = sorted(folder for folder in folders if folder not in SKIP_DIRS)
        parts = set(os.path.relpath(base, root).split(os.sep))
        bucket = preferred if parts & PRIORITY_DIRS else rest
        for name in sorted(names):
            bucket.append(os.path.join(base, name))
    yield from preferred
    yield from rest


