def _observation_text(observation: Any) -> str:
    if observation is None:
        return ""
    if isinstance(observation, str):
        return observation
    if isinstance(observation, Mapping):
        rows = observation.get("ui_nodes")
        if isinstance(rows, list):
            parts = []
            for node in rows:
                if isinstance(node, Mapping):
                    for name in ("text", "description", "value"):
                        if node.get(name):
                            parts.append(str(node[name]))
            return "\n".join(parts)
        try:
            return json.dumps(dict(observation), ensure_ascii=False)
        except (TypeError, ValueError):
            return ""
    return ""


def _scan_program(params: Mapping[str, Any], directories: list[str]) -> str:
    roots = params.get("scan_roots")
    if not isinstance(roots, (list, tuple)) or not roots:
        roots = list(DEFAULT_ZOTERO_ROOTS)
    expanded = []
    for raw in roots:
        path = _expand(raw)
        if path not in expanded:
            expanded.append(path)
    replacements = {
        "__MAX_FILES__": json.dumps(int(params.get("max_files", 240) or 240)),
        "__MAX_BYTES__": json.dumps(int(params.get("max_file_bytes", 15000000) or 15000000)),
        "__ROOTS__": json.dumps(expanded),
        "__GLOBAL_TEXT__": json.dumps(
            [str(item) for item in params.get("required_global_text") or []]
        ),
        "__GROUPS__": json.dumps(
            [
                {"name": str(group.get("name") or ""), "all": list(group.get("all") or [])}
                for group in params.get("required_groups") or []
                if isinstance(group, Mapping)
            ],
            ensure_ascii=False,
        ),
        "__DOCUMENT_DIRS__": json.dumps(directories),
        "__DOCUMENT_KEYS__": json.dumps(list(DEFAULT_SCAN_KEYS)),
    }
    program = LOCAL_STORAGE_SOURCE + _SCAN_PROGRAM
    for token, value in replacements.items():
        program = program.replace(token, value)
    return program


def _run_scan(controller: Any, program: str, timeout: int) -> dict[str, Any] | None:
    if controller is not None and hasattr(controller, "run_python_script"):
        try:
            raw = controller.run_python_script(program, timeout=timeout)
        except Exception:
            raw = None
        if isinstance(raw, Mapping):
            text = str(raw.get("stdout") or raw.get("output") or "").strip()
            if text:
                try:
                    parsed = json.loads(text)
                except ValueError:
                    parsed = None
                if isinstance(parsed, Mapping):
                    return dict(parsed)
    buffer = io.StringIO()
    try:
        with contextlib.redirect_stdout(buffer):
            exec(compile(program, "<scan>", "exec"), {"__name__": "__scan__"})
        parsed = json.loads(buffer.getvalue())
    except Exception:
        return None
    return dict(parsed) if isinstance(parsed, Mapping) else None


class OpenZoteroEvidenceEvaluator(BaseEvaluator):
    """Search the declared locations for the required text."""

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        timeout = int(params.get("timeout", 45) or 45)
        directories = _storage_directories(params)
        program = _scan_program(params, directories)
        result = _run_scan(context.get("controller"), program, timeout)
        if result is None:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="OpenZotero evidence scan did not return a readable result",
                metadata={"directories": directories},
            )

        observation_text = _observation_text(context.get("final_observation"))
        use_ui = bool(params.get("use_ui_evidence")) and bool(observation_text)
        whole_scan = bool(params.get("allow_aggregate_group_match", True))

        checks: list[dict[str, Any]] = []
        failures: list[str] = []

        def record(name: str, expected: Any, observed: Any, passed: bool) -> None:
            checks.append(
                {"check": name, "expected": expected, "observed": observed, "passed": bool(passed)}
            )
            if not passed:
                failures.append(name)

        global_rows = result.get("global") or {}
        missing_global = []
        for needle in params.get("required_global_text") or []:
            needle = str(needle)
            hits = list(global_rows.get(needle) or [])
            if not hits and use_ui and needle in observation_text:
                hits = ["observation"]
            if not hits:
                missing_global.append(needle)
        record("required_global_text", list(params.get("required_global_text") or []),
               {"absent": missing_global}, not missing_global)

        for group in result.get("groups") or []:
            if not isinstance(group, Mapping):
                continue
            name = str(group.get("name") or "")
            passed = bool(group.get("whole_scan")) if whole_scan else bool(group.get("one_source"))
            if not passed and use_ui:
                absent = [str(item) for item in group.get("absent") or []]
                passed = all(item in observation_text for item in absent)
            record("group:" + name, {"all": group.get("present") or []},
                   {"absent": group.get("absent") or []}, passed)

        passed = not failures
        return EvalResult(
            status=EvalStatus.PASS if passed else EvalStatus.FAIL,
            message=(
                "OpenZotero evidence contains the declared text"
                if passed
                else "OpenZotero evidence misses: " + ", ".join(failures)
            ),
            metadata={
                "checks": checks,
                "failures": failures,
                "sources": result.get("sources") or [],
                "notes": result.get("notes") or [],
                "file_count": result.get("file_count"),
                "directories": directories,
            },
        )


